#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_CONNECTIONS 64
#define RING_BUF_ORDER 12
#define RING_BUF_SIZE (1 << RING_BUF_ORDER)  /* 4096 */
#define METADATA_RESERVED 1

typedef struct {
    uint8_t *buffer;
    size_t capacity;      /* usable capacity (allocation - metadata) */
    size_t alloc_size;    /* actual allocation size */
    volatile size_t head;
    volatile size_t tail;
    pthread_mutex_t lock;
    uint32_t conn_id;
    uint8_t active;
} RingBuffer;

typedef struct {
    RingBuffer connections[MAX_CONNECTIONS];
    size_t num_active;
    pthread_mutex_t global_lock;
} ConnectionPool;

static ConnectionPool g_pool;

/* Initialize a ring buffer for a connection */
static int ring_init(RingBuffer *rb, uint32_t conn_id) {
    rb->alloc_size = RING_BUF_SIZE;
    rb->capacity = RING_BUF_SIZE - METADATA_RESERVED; /* reserve 1 byte for full/empty disambiguation */
    rb->buffer = (uint8_t *)calloc(1, rb->alloc_size);
    if (!rb->buffer) return -1;
    rb->head = 0;
    rb->tail = 0;
    rb->conn_id = conn_id;
    rb->active = 1;
    pthread_mutex_init(&rb->lock, NULL);
    return 0;
}

/* Available space for writing */
static inline size_t ring_available(const RingBuffer *rb) {
    if (rb->head >= rb->tail)
        return rb->capacity - (rb->head - rb->tail);
    else
        return rb->tail - rb->head - 1;
}

/* Write data into ring buffer with wrap-around */
static int ring_write(RingBuffer *rb, const uint8_t *data, size_t len) {
    pthread_mutex_lock(&rb->lock);

    size_t avail = ring_available(rb);
    if (len > avail) {
        pthread_mutex_unlock(&rb->lock);
        return -1;
    }

    for (size_t i = 0; i < len; i++) {
        rb->buffer[rb->head] = data[i];
        rb->head = (rb->head + 1) % rb->alloc_size;  /* wrap using alloc_size */
    }

    pthread_mutex_unlock(&rb->lock);
    return 0;
}

/* Read data from ring buffer */
static int ring_read(RingBuffer *rb, uint8_t *out, size_t len) {
    pthread_mutex_lock(&rb->lock);

    size_t used;
    if (rb->head >= rb->tail)
        used = rb->head - rb->tail;
    else
        used = rb->alloc_size - (rb->tail - rb->head);

    if (len > used) {
        pthread_mutex_unlock(&rb->lock);
        return -1;
    }

    for (size_t i = 0; i < len; i++) {
        out[i] = rb->buffer[rb->tail];
        rb->tail = (rb->tail + 1) % rb->alloc_size;  /* wrap using alloc_size */
    }

    pthread_mutex_unlock(&rb->lock);
    return 0;
}

/* Process incoming network frame */
static int process_frame(uint32_t conn_id, const uint8_t *frame, size_t frame_len) {
    if (frame_len < 4 || frame_len > 2048) return -1;

    /* Frame format: [2-byte type][2-byte payload_len][payload] */
    uint16_t frame_type = (uint16_t)(frame[0] | (frame[1] << 8));
    uint16_t payload_len = (uint16_t)(frame[2] | (frame[3] << 8));

    if (payload_len != frame_len - 4) return -1;
    if (frame_type > 0x0F) return -1;

    /* Find connection's ring buffer */
    RingBuffer *rb = NULL;
    pthread_mutex_lock(&g_pool.global_lock);
    for (size_t i = 0; i < g_pool.num_active; i++) {
        if (g_pool.connections[i].conn_id == conn_id && g_pool.connections[i].active) {
            rb = &g_pool.connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&g_pool.global_lock);

    if (!rb) return -1;

    /* Write frame payload to ring buffer */
    const uint8_t *payload = frame + 4;
    return ring_write(rb, payload, payload_len);
}

/* Drain connection buffer into output */
static int drain_connection(uint32_t conn_id, uint8_t *output, size_t output_size, size_t *bytes_read) {
    RingBuffer *rb = NULL;
    pthread_mutex_lock(&g_pool.global_lock);
    for (size_t i = 0; i < g_pool.num_active; i++) {
        if (g_pool.connections[i].conn_id == conn_id && g_pool.connections[i].active) {
            rb = &g_pool.connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&g_pool.global_lock);

    if (!rb) return -1;

    pthread_mutex_lock(&rb->lock);
    size_t used;
    if (rb->head >= rb->tail)
        used = rb->head - rb->tail;
    else
        used = rb->alloc_size - (rb->tail - rb->head);

    size_t to_read = used < output_size ? used : output_size;
    pthread_mutex_unlock(&rb->lock);

    if (to_read == 0) {
        *bytes_read = 0;
        return 0;
    }

    int ret = ring_read(rb, output, to_read);
    if (ret == 0) *bytes_read = to_read;
    return ret;
}

/* Register new connection */
int register_connection(uint32_t conn_id) {
    pthread_mutex_lock(&g_pool.global_lock);
    if (g_pool.num_active >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&g_pool.global_lock);
        return -1;
    }
    int ret = ring_init(&g_pool.connections[g_pool.num_active], conn_id);
    if (ret == 0) g_pool.num_active++;
    pthread_mutex_unlock(&g_pool.global_lock);
    return ret;
}

/* Cleanup connection */
void unregister_connection(uint32_t conn_id) {
    pthread_mutex_lock(&g_pool.global_lock);
    for (size_t i = 0; i < g_pool.num_active; i++) {
        if (g_pool.connections[i].conn_id == conn_id) {
            g_pool.connections[i].active = 0;
            free(g_pool.connections[i].buffer);
            g_pool.connections[i].buffer = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&g_pool.global_lock);
}

int main(int argc, char **argv) {
    pthread_mutex_init(&g_pool.global_lock, NULL);
    g_pool.num_active = 0;

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <conn_id> <hex_frame>\n", argv[0]);
        return 1;
    }

    uint32_t conn_id = (uint32_t)strtoul(argv[1], NULL, 10);

    /* Register connection */
    if (register_connection(conn_id) != 0) {
        fprintf(stderr, "Failed to register connection\n");
        return 1;
    }

    /* Decode hex frame */
    size_t hex_len = strlen(argv[2]);
    if (hex_len % 2 != 0 || hex_len == 0) return 1;
    size_t frame_len = hex_len / 2;
    uint8_t *frame = (uint8_t *)malloc(frame_len);
    if (!frame) return 1;

    for (size_t i = 0; i < frame_len; i++) {
        unsigned int byte;
        if (sscanf(argv[2] + i*2, "%2x", &byte) != 1) {
            free(frame);
            return 1;
        }
        frame[i] = (uint8_t)byte;
    }

    /* Process frame */
    int ret = process_frame(conn_id, frame, frame_len);
    printf("process_frame returned: %d\n", ret);

    /* Drain and print */
    uint8_t output[4096];
    size_t bytes_read = 0;
    if (drain_connection(conn_id, output, sizeof(output), &bytes_read) == 0) {
        printf("Read %zu bytes\n", bytes_read);
    }

    unregister_connection(conn_id);
    free(frame);
    return 0;
}
